import React, { ReactNode, useEffect, useState, Children, isValidElement, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedText from './AnimatedText';
import AnimatedList from './AnimatedList';

interface AnimatedContentProps {
  children: ReactNode;
  routeKey: string; // Used to trigger animations on route changes
  className?: string;
}

/**
 * This component wraps page content and handles:
 * 1. Page transitions (fade in/out)
 * 2. Processes children to apply animations in a sequential flow
 * 3. Ensures proper cleanup between route changes
 */
const AnimatedContent: React.FC<AnimatedContentProps> = ({ 
  children, 
  routeKey,
  className = ''
}) => {
  const [showContent, setShowContent] = useState(true);
  const [resetKey, setResetKey] = useState(0);
  const [processingDone, setProcessingDone] = useState(false);
  const animationQueue = useRef<ReactNode[]>([]);

  // Handle page transitions and reset animations
  useEffect(() => {
    // Reset animations and temporarily hide content
    setShowContent(false);
    setProcessingDone(false);

    // Reset animation state with new key
    setResetKey(prev => prev + 1);

    // Short delay before showing new content with fresh animations
    const timer = setTimeout(() => {
      setShowContent(true);
    }, 100);

    return () => clearTimeout(timer);
  }, [routeKey]);

  // Page transition variants
  const pageVariants = {
    initial: { opacity: 0 },
    animate: { opacity: 1, transition: { duration: 0.15 } },
    exit: { opacity: 0, transition: { duration: 0.1 } }
  };

  // Process React children to wrap text content in AnimatedText components
  // and create a sequential animation chain
  const processChildren = (children: ReactNode): ReactNode => {
    // Extract and process all children to prepare them for animation
    const processed: ReactNode[] = [];

    // Process each child
    Children.forEach(children, child => {
      if (!child) return;

      // Text nodes
      if (typeof child === 'string' && child.trim() !== '') {
        processed.push(
          <AnimatedText 
            key={`text-${processed.length}`}
            text={child}
            onComplete={() => animateNext()}
          />
        );
        return;
      }

      // Skip non-react elements
      if (!isValidElement(child)) return;

      // Skip certain elements we don't want to animate
      const excludedElements = ['img', 'button', 'input', 'textarea'];
      if (excludedElements.includes(child.type as string)) {
        processed.push(child);
        return;
      }

      // Handle lists with AnimatedList
      if (child.type === 'ul' || child.type === 'ol') {
        const listItems = Children.toArray(child.props.children);
        processed.push(
          <AnimatedList 
            key={`list-${processed.length}`}
            component={child.type as 'ul' | 'ol'}
            className={child.props.className || ''}
            onComplete={() => animateNext()}
          >
            {listItems}
          </AnimatedList>
        );
        return;
      }

      // Special handling for common text elements
      const textElements = ['p', 'h1', 'h2', 'h3', 'h4', 'span', 'li', 'a'];
      if (textElements.includes(child.type as string) && 
          React.Children.count(child.props.children) === 1 &&
          typeof child.props.children === 'string') {
        // Simple text element with just a string as child
        const text = child.props.children;
        const elementType = child.type as 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div' | 'li' | 'a';

        processed.push(
          <AnimatedText 
            key={`elem-${processed.length}`}
            text={text} 
            element={elementType}
            className={child.props.className || ''}
            preserveWhitespace={true}
            onComplete={() => animateNext()}
          />
        );
        return;
      }

      // For elements with multiple children, recursively process them
      if (child.props.children) {
        const newChildren = processChildren(child.props.children);
        const { children: _, ...otherProps } = child.props;

        processed.push(
          React.cloneElement(
            child,
            { ...otherProps, key: `container-${processed.length}` },
            newChildren
          )
        );
        return;
      }

      // Default: return unchanged
      processed.push(child);
    });

    animationQueue.current = processed;

    // Return only the first item to start the animation chain
    if (processed.length > 0) {
      const [firstElement, ...rest] = processed;
      return firstElement;
    }

    return null;
  };

  // Function to display the next element in the animation queue
  const animateNext = () => {
    // Remove the first item (which was just displayed)
    animationQueue.current.shift();

    // If there are more items, trigger a re-render to show the next one
    setResetKey(prev => prev + 1);

    // If no more items, mark as done
    if (animationQueue.current.length === 0) {
      setProcessingDone(true);
    }
  };

  // Initial processing of children
  const initialContent = showContent ? processChildren(children) : null;

  return (
    <AnimatePresence mode="wait">
      {showContent && (
        <motion.div
          key={`animated-content-${routeKey}-${resetKey}`}
          initial="initial"
          animate="animate"
          exit="exit"
          variants={pageVariants}
          className={`animated-content-wrapper ${className}`}
        >
          {initialContent}
          {/* Display the processed content as a flat array */}
          {processingDone && children}
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default AnimatedContent;
